// AIM plugin for OpenCode v1. Generated by `aim install opencode`; edit with
// care, `aim install` overwrites this file.
//
// It spawns `aim hook opencode <event>` with a JSON payload on stdin and
// treats stdout as Markdown context for the session. Errors are swallowed:
// AIM must never break the agent.
import { spawn } from "node:child_process"

const BIN = __AIM_BIN__
const HOOK_TIMEOUT_MS = 10_000
const WAKE_CAP = 5
const WAKE_WINDOW_MS = 10 * 60_000

// run spawns the hook and resolves to its trimmed stdout ("" on any error).
// kill() stops it early.
function run(event, payload, timeoutMs) {
  let child
  const promise = new Promise((resolve) => {
    let out = ""
    let timer
    try {
      child = spawn(BIN, ["hook", "opencode", event], { stdio: ["pipe", "pipe", "ignore"] })
    } catch {
      resolve("")
      return
    }
    if (timeoutMs) timer = setTimeout(() => child.kill(), timeoutMs)
    child.stdout.on("data", (d) => (out += d))
    child.on("error", () => {
      clearTimeout(timer)
      resolve("")
    })
    child.on("close", () => {
      clearTimeout(timer)
      resolve(out.trim())
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
  return { promise, kill: () => child && child.kill() }
}

function sessionOf(event) {
  const p = (event && event.properties) || {}
  return p.sessionID ?? (p.info && p.info.id) ?? p.id
}

export const AimPlugin = async ({ client, directory }) => {
  const agents = new Map() // session id -> agent name
  const watchers = new Map() // session id -> in-flight watch
  const wakes = new Map() // session id -> wake timestamps

  const payload = (sessionID) => ({ sessionID, directory, agent: agents.get(sessionID) ?? "" })

  const send = async (sessionID, text, wake) => {
    const parts = [{ type: "text", text }]
    const body = wake ? { parts } : { noReply: true, parts }
    await client.session.prompt({ path: { id: sessionID }, body })
  }

  const wakeAllowed = (sessionID) => {
    const now = Date.now()
    const recent = (wakes.get(sessionID) ?? []).filter((t) => now - t < WAKE_WINDOW_MS)
    wakes.set(sessionID, recent)
    return recent.length < WAKE_CAP
  }

  const inject = async (event, sessionID) => {
    const text = await run(event, payload(sessionID), HOOK_TIMEOUT_MS).promise
    if (text) await send(sessionID, text, false)
  }

  const startWatch = (sessionID) => {
    if (watchers.has(sessionID) || !wakeAllowed(sessionID)) return
    const w = run("watch", payload(sessionID), 0)
    watchers.set(sessionID, w)
    w.promise
      .then(async (text) => {
        if (watchers.get(sessionID) !== w) return
        watchers.delete(sessionID)
        if (!text || !wakeAllowed(sessionID)) return
        wakes.get(sessionID).push(Date.now())
        await send(sessionID, text, true)
      })
      .catch(() => watchers.delete(sessionID))
  }

  const stopWatch = (sessionID) => {
    const w = watchers.get(sessionID)
    watchers.delete(sessionID)
    if (w) w.kill()
  }

  return {
    event: async ({ event }) => {
      try {
        const sessionID = sessionOf(event)
        if (!sessionID) return
        switch (event.type) {
          case "session.created":
            await inject("session-start", sessionID)
            break
          case "session.idle":
            startWatch(sessionID)
            break
          case "session.deleted":
            stopWatch(sessionID)
            agents.delete(sessionID)
            wakes.delete(sessionID)
            await run("session-end", payload(sessionID), HOOK_TIMEOUT_MS).promise
            break
        }
      } catch {}
    },
    "chat.message": async (input) => {
      try {
        const sessionID = input && input.sessionID
        if (!sessionID) return
        if (input.agent) agents.set(sessionID, input.agent)
        // A user turn supersedes any pending watch; the next idle restarts it.
        stopWatch(sessionID)
        // Not awaited: the prompt call must not block the message in flight.
        inject("prompt", sessionID).catch(() => {})
      } catch {}
    },
  }
}
